//! clang 19's answers to the feature-test hooks ([cpp.cond]/5, Table 23,
//! and clang's `__has_*` extensions): [`ClangFeatures`].
//!
//! The answers come from `features_table.rs`, generated by
//! `scripts/gen-features.sh`, which probes `clang++-19 -E` for every
//! builtin, attribute, feature and keyword spelling clang knows, under each
//! supported target and standard and under each [`FeatureFlag`]. Lookups are
//! binary searches in sorted static arrays; nothing is allocated per query.
//! See `spec/pp.md` §"Feature queries" for the normative description.

use std::cmp::Ordering;

use kiln_lex::Std;

use crate::builtin::{FeatureQueries, TargetQuery};

#[path = "features_table.rs"]
mod table;

pub use table::FeatureFlag;

/// A table entry: (key, value, mask of the configurations it holds in).
struct Entry(&'static str, u32, u16);

/// An answer that differs from the base table when a flag is set:
/// (flag, query, key, value, configuration mask).
struct Overlay(FeatureFlag, Kind, &'static str, u32, u16);

/// The query a table answers. Declaration order is the overlay sort order.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
enum Kind {
    Feature,
    Extension,
    Builtin,
    ConstexprBuiltin,
    Attribute,
    DeclspecAttribute,
    CppAttribute,
    Keyword,
}

/// The targets the tables were generated for, in configuration-bit order.
const TARGETS: [&str; 2] = ["aarch64", "x86_64"];

/// Standards in configuration-bit order (C++03 answers as C++98).
fn std_index(std: Std) -> u16 {
    match std {
        Std::Cxx98 | Std::Cxx03 => 0,
        Std::Cxx11 => 1,
        Std::Cxx14 => 2,
        Std::Cxx17 => 3,
        Std::Cxx20 => 4,
        Std::Cxx23 => 5,
        Std::Cxx26 => 6,
    }
}

/// A target triple, normalized as clang's `TargetInfo` sees it.
#[derive(Clone, Debug, PartialEq, Eq)]
struct Triple {
    /// Index into [`TARGETS`].
    target: u16,
    arch: String,
    vendor: String,
    os: String,
    env: String,
}

impl Triple {
    /// `arch-vendor-os-env`, or `arch-os-env` with the vendor omitted
    /// (`x86_64-linux-gnu`). `None` unless the arch is aarch64/arm64 or
    /// `x86_64`/`amd64` and the OS is Linux with a GNU environment.
    fn parse(triple: &str) -> Option<Triple> {
        let mut parts: Vec<&str> = triple.split('-').collect();
        if parts.len() == 3 && parts[1].starts_with("linux") {
            parts.insert(1, "unknown");
        }
        let [arch, vendor, os, env] = parts[..] else {
            return None;
        };
        let target = match arch {
            "aarch64" | "arm64" => 0,
            "x86_64" | "amd64" => 1,
            _ => return None,
        };
        if !os.starts_with("linux") || env_kind(env) != Some(EnvKind::Gnu) {
            return None;
        }
        Some(Triple {
            target,
            arch: TARGETS[usize::from(target)].to_owned(),
            vendor: vendor.to_owned(),
            os: os.to_owned(),
            env: env.to_owned(),
        })
    }
}

/// The environments clang's triple parser tells apart that matter here.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum EnvKind {
    Gnu,
    Other,
}

/// LLVM `Triple::parseEnvironment` restricted to the GNU family: the
/// parser takes the first listed prefix that matches, and only a plain
/// `gnu` prefix means `Triple::GNU`. `None` for an unknown environment.
fn env_kind(name: &str) -> Option<EnvKind> {
    const OTHER: [&str; 12] = [
        "eabihf",
        "eabi",
        "gnuabin32",
        "gnuabi64",
        "gnueabihft64",
        "gnueabihf",
        "gnueabi",
        "gnuf32",
        "gnuf64",
        "gnusf",
        "gnux32",
        "gnu_ilp32",
    ];
    if OTHER.iter().any(|p| name.starts_with(p)) || name.starts_with("code16") {
        return Some(EnvKind::Other);
    }
    if name.starts_with("gnut64") {
        return Some(EnvKind::Other);
    }
    if name.starts_with("gnu") {
        return Some(EnvKind::Gnu);
    }
    None
}

/// clang 19's [`FeatureQueries`] for one target, standard and set of
/// driver options.
///
/// `-march`/`-mcpu`/`-m<feature>` are not modeled: `__has_builtin` answers
/// for target builtins are those of the triple's default CPU.
#[derive(Clone, Debug)]
pub struct ClangFeatures {
    triple: Triple,
    /// The configuration bit (`target * 7 + std`).
    bit: u16,
    /// Set flags the target supports, sorted and deduplicated.
    flags: Vec<FeatureFlag>,
}

impl ClangFeatures {
    /// The answers for `triple` (`aarch64-unknown-linux-gnu`,
    /// `x86_64-unknown-linux-gnu`, or the same without the vendor) in
    /// `std` with `flags` set. Flags clang rejects for the target (the
    /// aarch64-only `-fptrauth-*`, x86_64-only `-fsanitize=numerical`) are
    /// ignored. `None` for any other target.
    pub fn new(triple: &str, std: Std, flags: &[FeatureFlag]) -> Option<ClangFeatures> {
        let triple = Triple::parse(triple)?;
        let bit = 1u16 << (triple.target * 7 + std_index(std));
        let mut flags: Vec<FeatureFlag> =
            flags.iter().copied().filter(|f| f.supported() & bit != 0).collect();
        flags.sort_unstable();
        flags.dedup();
        Some(ClangFeatures { triple, bit, flags })
    }

    /// [`ClangFeatures::new`] with the flags a clang command line sets:
    /// each option of [`FeatureFlag::options`], with `-fno-X` undoing `-fX`
    /// and vice versa, `-fsanitize=a,b` / `-fno-sanitize=a,b` lists,
    /// `-fsanitize-coverage=...`, `-fno-cxx-exceptions`, and
    /// `-std=gnu++NN` / `-std=c++NN` for [`FeatureFlag::GnuMode`]. Other
    /// arguments are ignored; the standard itself comes from `std`.
    pub fn from_args<S: AsRef<str>>(triple: &str, std: Std, args: &[S]) -> Option<ClangFeatures> {
        let mut set: Vec<FeatureFlag> = Vec::new();
        let mut toggle = |f: Option<FeatureFlag>, on: bool| {
            if let Some(f) = f {
                set.retain(|&g| g != f);
                if on {
                    set.push(f);
                }
            }
        };
        for arg in args {
            let arg = arg.as_ref();
            if let Some(list) = arg.strip_prefix("-fsanitize=") {
                for s in list.split(',') {
                    toggle(flag_with_option(&format!("-fsanitize={s}")), true);
                }
            } else if let Some(list) = arg.strip_prefix("-fno-sanitize=") {
                for s in list.split(',') {
                    toggle(flag_with_option(&format!("-fsanitize={s}")), false);
                }
            } else if let Some(v) = arg.strip_prefix("-fsanitize-coverage=") {
                toggle(flag_named("SanitizeCoverage"), !v.is_empty());
            } else if arg.starts_with("-fno-sanitize-coverage=") {
                toggle(flag_named("SanitizeCoverage"), false);
            } else if let Some(s) = arg.strip_prefix("-std=") {
                toggle(flag_named("GnuMode"), s.starts_with("gnu"));
            } else if arg == "-fno-cxx-exceptions" {
                toggle(flag_named("NoExceptions"), true);
            } else if arg == "-fcxx-exceptions" {
                toggle(flag_named("NoExceptions"), false);
            } else if let Some(f) = flag_with_option(arg) {
                toggle(Some(f), true);
            } else if let Some(rest) = arg.strip_prefix("-fno-") {
                toggle(flag_with_option(&format!("-f{rest}")), false);
            } else if let Some(rest) = arg.strip_prefix("-f") {
                toggle(flag_with_option(&format!("-fno-{rest}")), false);
            }
        }
        ClangFeatures::new(triple, std, &set)
    }

    /// The flags in effect, in overlay order.
    pub fn flags(&self) -> &[FeatureFlag] {
        &self.flags
    }

    /// The answer of `kind` for `key` (already normalized).
    fn lookup(&self, kind: Kind, table: &[Entry], key: &str) -> u32 {
        let lo = table.partition_point(|e| e.0 < key);
        let mut v = 0;
        for e in table[lo..].iter().take_while(|e| e.0 == key) {
            if e.2 & self.bit != 0 {
                v = e.1;
            }
        }
        for &f in &self.flags {
            let lo = table::OVERLAYS.partition_point(|o| {
                (o.0, o.1).cmp(&(f, kind)).then_with(|| o.2.cmp(key)) == Ordering::Less
            });
            for o in
                table::OVERLAYS[lo..].iter().take_while(|o| o.0 == f && o.1 == kind && o.2 == key)
            {
                if o.4 & self.bit != 0 {
                    v = o.3;
                }
            }
        }
        v
    }
}

/// The flag whose first probed option is `option`.
fn flag_with_option(option: &str) -> Option<FeatureFlag> {
    FeatureFlag::ALL.iter().copied().find(|f| f.options().first() == Some(&option))
}

/// The flag named `name` (Debug spelling), if the table has it.
fn flag_named(name: &str) -> Option<FeatureFlag> {
    FeatureFlag::ALL.iter().copied().find(|f| format!("{f:?}") == name)
}

/// `__x__` -> `x` (clang `HasFeature`, `normalizeAttrName`).
fn strip_dunder(name: &str) -> &str {
    if name.len() >= 4 && name.starts_with("__") && name.ends_with("__") {
        &name[2..name.len() - 2]
    } else {
        name
    }
}

impl FeatureQueries for ClangFeatures {
    fn has_feature(&self, name: &str) -> bool {
        self.lookup(Kind::Feature, table::FEATURE, strip_dunder(name)) != 0
    }

    fn has_extension(&self, name: &str) -> bool {
        self.lookup(Kind::Extension, table::EXTENSION, strip_dunder(name)) != 0
    }

    fn has_builtin(&self, name: &str) -> u32 {
        self.lookup(Kind::Builtin, table::BUILTIN, name)
    }

    fn has_constexpr_builtin(&self, name: &str) -> bool {
        self.lookup(Kind::ConstexprBuiltin, table::CONSTEXPR_BUILTIN, name) != 0
    }

    fn has_attribute(&self, name: &str) -> u32 {
        self.lookup(Kind::Attribute, table::ATTRIBUTE, strip_dunder(name))
    }

    fn has_cpp_attribute(&self, scope: Option<&str>, name: &str) -> u32 {
        // clang `normalizeAttrScopeName` / `normalizeAttrName`.
        let scope = scope.map(|s| match s {
            "__gnu__" => "gnu",
            "_Clang" => "clang",
            s => s,
        });
        match scope {
            None => self.lookup(Kind::CppAttribute, table::CPP_ATTRIBUTE, strip_dunder(name)),
            Some(s) => {
                let name = if matches!(s, "gnu" | "clang") { strip_dunder(name) } else { name };
                let key = format!("{s}::{name}");
                self.lookup(Kind::CppAttribute, table::CPP_ATTRIBUTE, &key)
            }
        }
    }

    fn has_declspec_attribute(&self, name: &str) -> bool {
        self.lookup(Kind::DeclspecAttribute, table::DECLSPEC_ATTRIBUTE, name) != 0
    }

    fn is_keyword(&self, name: &str) -> bool {
        self.lookup(Kind::Keyword, table::KEYWORD, name) != 0
    }

    /// clang `isTargetArch` & co. (PPMacroExpansion.cpp) for a Linux GNU
    /// triple: names compare case-insensitively; an arch name matches if
    /// LLVM parses it to the target's arch (`aarch64`, `arm64`; `x86_64`,
    /// `x86_64h`, `amd64`; LLVM's ARM parser also accepts many suffixed
    /// spellings such as `aarch64v8a`, which are not modeled); an OS name
    /// matches if LLVM's prefix parse gives Linux (`linux*`); an
    /// environment if it gives GNU (`gnu*` except `gnueabi*`, `gnux32*`,
    /// ...). There is no Darwin target variant, so the `variant` queries
    /// are false.
    fn is_target(&self, query: TargetQuery, name: &str) -> bool {
        let lower = name.to_ascii_lowercase();
        let t = &self.triple;
        match query {
            TargetQuery::Arch => {
                let parsed = match lower.as_str() {
                    "aarch64" | "arm64" => Some(0),
                    "x86_64" | "x86_64h" | "amd64" => Some(1),
                    _ => None,
                };
                parsed == Some(t.target) || lower == t.arch
            }
            TargetQuery::Vendor => {
                let v = if t.vendor.is_empty() { "unknown" } else { t.vendor.as_str() };
                lower == v.to_ascii_lowercase()
            }
            TargetQuery::Os => lower.starts_with("linux") && t.os.starts_with("linux"),
            TargetQuery::Environment => {
                env_kind(&lower) == Some(EnvKind::Gnu) && env_kind(&t.env) == Some(EnvKind::Gnu)
            }
            TargetQuery::VariantOs | TargetQuery::VariantEnvironment => false,
        }
    }

    fn flt_eval_method(&self) -> i32 {
        table::FLT_EVAL_METHOD[usize::from(self.triple.target)]
    }
}
